/* Czech Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Jan": "God is gracious — Hebrew Yohanan", "Marie": "The most common Czech feminine name.", "Petr": "rock, stone — Greek petros", "Jana": "God is gracious — Hebrew Yohanan", "Josef": "God increases — Hebrew Yosef", "Eva": "life — Hebrew", "Novak": "The most common Czech surname; feminine form Novakova.", "Svoboda": "A beloved surname meaning freedom.", "Novotny": "Feminine form Novotna.", "Dvorak": "The family name of composer Antonin Dvorak."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Jan';
console.log(lookup(q));

